#!/usr/bin/env python3
"""Build a bounded 2020-03 source-only outTemp proposal from frozen evidence."""
import csv,json,hashlib
from pathlib import Path
R=Path(__file__).resolve().parents[1]; P=R/'proposals/restored_source_only_2020_march_outtemp'; P.mkdir(parents=True,exist_ok=True)
review=json.loads((R/'data/source_only_strict_2013_2020_review.json').read_text())
ctx=json.loads((R/'data/source_only_strict_2020_exact_context.json').read_text())['rows']; regional_ctx=json.loads((R/'data/source_only_strict_2013_2020_review.json').read_text())['context_rows_2020']
targets=[1583078400,1583097600]
rows={int(r['dateTime']):r for r in review['candidates'] if int(r['dateTime']) in targets}
assert set(rows)==set(targets)
local={1583078400:{'target_exists':False,'change_events':0,'nearest_before':{'dateTime':1583069100,'outTemp':7.8,'outHumidity':68.3},'nearest_after':{'dateTime':1583089800,'outTemp':5.3,'outHumidity':85}},1583097600:{'target_exists':False,'change_events':0,'nearest_before':{'dateTime':1583095800,'outTemp':5.3,'outHumidity':88.7},'nearest_after':{'dateTime':1583098500,'outTemp':5.3,'outHumidity':89.8}}}
for t,r in rows.items():
 assert r['usUnits']==17 and r['interval']==5 and r['old_units']==17 and r['old_interval']==5 and r['old_temp']==r['outTemp']
 assert r['target_time'] is None and r['site_old_time'] is None and r['main_time'] is None and r['gw1000_time'] is None and r['target_change_events']==0
 assert local[t]['target_exists'] is False and local[t]['change_events']==0

def write(name,obj): (P/name).write_text(json.dumps(obj,ensure_ascii=False,indent=2)+'\n')
source=[];regional=[];metadata=[];ops=[]
for t in targets:
 r=rows[t];d=ctx[str(t)];window=d['window'];assert len(window)==7;refwindow=[x for x in regional_ctx if int(x['target_epoch'])==t];assert len(refwindow)==25
 exact=next(x for x in window if int(x['source_epoch'])==t)
 before=next(x for x in window if int(x['source_epoch'])==t-300);after=next(x for x in window if int(x['source_epoch'])==t+300)
 assert r['outTemp']==exact['outTemp'] and r['old_rh']==exact['outHumidity'] and r['old_rain']==exact['rain'] and r['old_rate']==exact['rainRate'] and r['old_wind']==exact['windSpeed']
 assert r['outTemp']==before['outTemp'] or abs(r['outTemp']-before['outTemp'])<=0.2
 assert abs(r['outTemp']-after['outTemp'])<=0.2
 reg={'timestamp':t,'window_start':refwindow[0]['source_epoch'],'window_end':refwindow[-1]['source_epoch'],'rows':refwindow}
 regional.append(reg)
 source.append({'timestamp':t,'utc':r['utc'],'source_databases':['old_weewx','weewx_WH1080'],'source_concordance':'Exact target values from old_weewx candidate and weewx_WH1080 exact context agree for the five audited primary fields; two archive copies are treated as dependent copies, not independent sensors.','usUnits':r['usUnits'],'interval':r['interval'],'source_values':{k:r[k] for k in ['outTemp','outHumidity','rain','rainRate','windSpeed']},'archive_row_presence_by_database':{'loucka_reconstruction':False,'pocasi-loucka.eu':False,'pocasi-loucka.eu_GW1000':False,'pocasi-loucka.eu_old':False,'old_weewx':True,'weewx_WH1080':True},'change_events':r['target_change_events'],'source_context_5min':{'before':before,'exact':exact,'after':after},'regional_window':{'n':25,'luha_temp_min':min(x['luhamet_temp_c'] for x in refwindow),'luha_temp_max':max(x['luhamet_temp_c'] for x in refwindow),'luha_rh_min':min(x['luhamet_rh_pct'] for x in refwindow),'luha_rh_max':max(x['luhamet_rh_pct'] for x in refwindow)},'live_reconstruction_neighbors':local[t]})
 reason=('RESTORED; MODERATE provenance. Exact 5-minute outTemp source value is present and identical in old_weewx and weewx_WH1080 (copies are not treated as independent sensors); usUnits=17/interval=5. The exact target row is absent from reconstruction, pocasi-loucka.eu, pocasi-loucka.eu_GW1000 and pocasi-loucka.eu_old; old_weewx and weewx_WH1080 contain matching source rows. No target change event was found in the frozen evidence; current READ-ONLY checks reconfirmed the matching source rows and reconstruction target absence. Source outTemp is continuous with adjacent source temperatures and the independent LuhaMet temperature context shows a stable approximately -1.3 to -1.4 C local-minus-reference offset around the candidate. At 2020-03-01 21:20 UTC, local reconstruction neighbors are 5.3 C on both sides and the source value is 5.4 C; at 16:00, source temperature follows the local cooling and regional context but nearest target rows are several hours away. Uncertainty: exact historical archive origin and reason for target row omission are unknown; source RH at these timestamps (11% and 31%) conflicts with local/reference humidity, so RH is explicitly excluded and possible historical row removal due another-field quality cannot be ruled out. Restore outTemp only; no RH, rain/rainRate, wind or other field synthesized.')
 op={'operation':'insert','timestamp':t,'variable':'outTemp','new_value':r['outTemp'],'expected_old_value':None,'source_database':'old_weewx','source_time':t,'source_value':r['outTemp'],'reason':reason,'us_units':17,'interval_minutes':5};ops.append(op)
 metadata.append({'timestamp':t,'utc':r['utc'],'classification':'RESTORED','confidence':'MODERATE','operation':'insert outTemp only','source_archive':'old_weewx; exact target outTemp concordance also in weewx_WH1080; copies dependent','source_value':r['outTemp'],'usUnits':17,'interval_minutes':5,'target_expected_state':'No archive row at exact target; all candidate fields NULL by row absence; reconstruction history has zero events at target.','outTemp_evidence':'Source exact copies; adjacent source temperatures differ by <=0.2 C; LuhaMet window 25 exact 5-minute context rows; local reconstruction target exists absent and nearest surrounding observations recorded.','context_field_flags':{'outHumidity':'REVIEW_REQUIRED_SOURCE_SENSOR_CONFLICT; source 11%/31% conflicts with LuhaMet/local humidity, excluded','rain':'source zero, not independently verified as original local measurement; excluded','rainRate':'source zero, not independently verified; excluded','windSpeed':'source copies agree, but no field-specific original-unit/migration review in this pilot; excluded'},'uncertainty':'MODERATE provenance; no proof why target rows were omitted or whether earlier cleaning removed rows because of RH. No individual prediction interval applies to restored measurements.','approval':'NOT_APPROVED','actual_mcp_dry_run':'NOT_RUN','application':'NOT_APPLIED'})
write('source_snapshot.json',source);write('regional_context_snapshot.json',regional);write('local_target_state.json',local);write('candidate_metadata.json',metadata);write('corrections.json',ops)
with (P/'corrections.csv').open('w',newline='') as f:
 w=csv.DictWriter(f,fieldnames=list(ops[0]));w.writeheader();w.writerows(ops)
ex=[{'timestamp':t,'variable':v,'status':'EXCLUDED','reason':reason} for t in targets for v,reason in [('outHumidity','Source values conflict with local and LuhaMet context; likely sensor issue at timestamp; no restoration.'),('rain','Source zero only; no sufficient local tipping-bucket/counter provenance.'),('rainRate','Source zero only; known GW1000/GW3000 rate semantics unresolved.'),('windSpeed','No pilot-specific field-unit/migration validation.'),('all other fields','Not populated by evidence; do not synthesize.')]]
with (P/'excluded_fields.csv').open('w',newline='') as f:
 w=csv.DictWriter(f,fieldnames=['timestamp','variable','status','reason']);w.writeheader();w.writerows(ex)
write('lineage_decision.json',{'classification':'RESTORED','confidence':'MODERATE','decision':'Propose two source-only outTemp inserts; exclude all other fields.','basis':['Exact source target values in old_weewx and weewx_WH1080, source copies treated as dependent','usUnits=17 and interval=5; aligned UTC 5-minute grid','frozen six-archive exact-target presence/history evidence plus current READ-ONLY recheck of old/WH values and reconstruction target absence','source outTemp agrees smoothly with adjacent source temperatures','independent regional temperature context and local target neighborhood support temperature plausibility, strongest at 21:20 UTC'],'limitations':['Owner-attested archive ecosystem, exact origin and prior cleaning rules unknown','Source RH at candidate targets conflicts strongly with local/reference humidity; potential whole-row omission due RH cannot be excluded','No single archive copy is asserted to be original unmodified sensor stream','No writes, staging, dry-run, or application']})
write('offline_simulation.json',{'simulation':'local in-memory proposal accounting only','operations':2,'physical_insert_rows':2,'updates':0,'database_access':'NONE','database_writes':0,'staging':False,'actual_mcp_dry_run':'NOT_RUN','application':'NOT_APPLIED'})
(P/'simulate.py').write_text('''#!/usr/bin/env python3\nimport json\nfrom pathlib import Path\np=Path(__file__).resolve().parent\nops=json.loads((p/'corrections.json').read_text())\nassert len(ops)==2 and all(o['operation']=='insert' and o['variable']=='outTemp' for o in ops)\nprint(json.dumps({'simulation':'local in-memory proposal accounting only','operations':2,'physical_insert_rows':2,'updates':0,'database_access':'NONE','database_writes':0,'staging':False,'application':'NOT_APPLIED'},indent=2))\n''')
(P/'validate.py').write_text('''#!/usr/bin/env python3\nimport csv,json,hashlib\nfrom pathlib import Path\np=Path(__file__).resolve().parent\nops=json.loads((p/'corrections.json').read_text());src=json.loads((p/'source_snapshot.json').read_text());meta=json.loads((p/'candidate_metadata.json').read_text());refs=json.loads((p/'regional_context_snapshot.json').read_text());local=json.loads((p/'local_target_state.json').read_text());manifest=json.loads((p/'manifest.json').read_text())\nassert len(ops)==len(src)==len(meta)==len(refs)==2 and len({o['timestamp'] for o in ops})==2\nfor o,m,s,r in zip(ops,meta,src,refs):\n t=o['timestamp'];assert o['variable']=='outTemp' and o['operation']=='insert' and o['expected_old_value'] is None and o['new_value']==o['source_value']==s['source_values']['outTemp']==m['source_value']\n assert 'RESTORED' in o['reason'] and 'MODERATE provenance' in o['reason'] and 'Uncertainty:' in o['reason']\n assert s['source_databases']==['old_weewx','weewx_WH1080'] and s['usUnits']==17 and s['interval']==5 and s['change_events']==0\n assert s['source_values']['outTemp']==s['source_context_5min']['before']['outTemp'] or abs(s['source_values']['outTemp']-s['source_context_5min']['before']['outTemp'])<=0.2\n assert abs(s['source_values']['outTemp']-s['source_context_5min']['after']['outTemp'])<=0.2\n assert s['archive_row_presence_by_database']=={'loucka_reconstruction':False,'pocasi-loucka.eu':False,'pocasi-loucka.eu_GW1000':False,'pocasi-loucka.eu_old':False,'old_weewx':True,'weewx_WH1080':True}\n assert len(r['rows'])==25 and m['context_field_flags']['outHumidity'].startswith('REVIEW_REQUIRED') and local[str(t)]['target_exists'] is False\n assert m['classification']=='RESTORED' and m['confidence']=='MODERATE' and m['approval']=='NOT_APPROVED' and m['actual_mcp_dry_run']=='NOT_RUN' and m['application']=='NOT_APPLIED'\nfor item in manifest['files']:\n b=(p/item['path']).read_bytes();assert len(b)==item['bytes'] and hashlib.sha256(b).hexdigest()==item['sha256'],item['path']\nprint('PASS: two source-only outTemp RESTORED/MODERATE candidates; field-separated RH exclusion; exact-copy, context, target state, uncertainty, manifest; no writes.')\n''')
(P/'README.md').write_text('''# 2020-03 source-only outTemp pilot\n\nTwo five-minute target timestamps (2020-03-01 16:00 and 21:20 UTC) have identical outTemp values in old_weewx and weewx_WH1080. The archives are dependent copies, not independent sensors. Frozen source-first evidence reports the rows absent from reconstruction, pocasi-loucka.eu, GW1000 and pocasi-loucka.eu_old, with no target change events. A 2026-11-14 READ-ONLY check reconfirmed the exact source rows and reconstruction absence.\n\nThe proposal restores outTemp only (RESTORED/MODERATE). Temperature values are smooth against neighboring source rows and plausible against the 25-row LuhaMet context. The 21:20 candidate also agrees with local reconstruction neighbors (5.3 C on each side; candidate 5.4 C). Candidate source RH (11% and 31%) is strongly inconsistent with nearby context and is excluded. The reason for historical target omission remains unknown, including the possibility that a whole row was omitted due to RH quality. No other variables are proposed.\n\nLocal validator: `python3 proposals/restored_source_only_2020_march_outtemp/validate.py` from project root (or `python3 validate.py` from this directory). Local simulation: `python3 simulate.py`; no database access. Draft only: NOT_APPROVED, NOT_RUN, NOT_APPLIED.\n''')
(P/'PRE_APPLICATION_CHECKLIST.md').write_text('''# Pre-application checklist — 2020 March outTemp\n\nBefore any separately approved action: recheck all six archive exact timestamp state and target change history; verify expected absence and source values; review RH anomaly and historical omission uncertainty; confirm no duplicate active operation; make a restorable backup; validate MCP payload and batch limit; obtain explicit approval; perform only then the approved MCP dry-run; record RESTORED/MODERATE and uncertainty in audit reason; if separately approved, apply and verify outTemp and unrelated fields, with rollback from backup on invariant failure. Current state is NOT_APPROVED / NOT_RUN / NOT_APPLIED. No staging or writes.\n''')
# Deterministic package manifest.
files=sorted(q.name for q in P.iterdir() if q.is_file() and q.name!='manifest.json')
(P/'manifest.json').write_text(json.dumps({'schema':'proposal-manifest-v1','package':'restored-source-only-2020-march-outtemp','classification':'RESTORED','confidence':'MODERATE','operation_count':2,'files':[{'path':f,'bytes':(P/f).stat().st_size,'sha256':hashlib.sha256((P/f).read_bytes()).hexdigest()} for f in files]},indent=2)+'\n')
print('built',len(files)+1,'files')
